import heapq

class Solution:
    def isPossible(self, target: list[int]) -> bool:
        total = sum(target)
        max_heap = [-x for x in target]
        heapq.heapify(max_heap)
        while True:
            largest = -heapq.heappop(max_heap)
            rest = total - largest
            if largest == 1 or rest == 1:
                return True
            if rest == 0 or largest <= rest or largest % rest == 0:
                return False
            prev = largest % rest
            total = rest + prev
            heapq.heappush(max_heap, -prev)

#include <vector>
#include <queue>
#include <numeric>

class Solution {
public:
    bool isPossible(std::vector<int>& target) {
        long long total = 0;
        std::priority_queue<long long> maxHeap;
        for (int x : target) {
            total += x;
            maxHeap.push(x);
        }
        while (true) {
            long long largest = maxHeap.top();
            maxHeap.pop();
            long long rest = total - largest;
            if (largest == 1 || rest == 1) return true;
            if (rest == 0 || largest <= rest || largest % rest == 0) return false;
            long long prev = largest % rest;
            total = rest + prev;
            maxHeap.push(prev);
        }
    }
};

import java.util.*;

class Solution {
    public boolean isPossible(int[] target) {
        long total = 0;
        PriorityQueue<Long> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
        for (int x : target) {
            total += x;
            maxHeap.offer((long)x);
        }
        while (true) {
            long largest = maxHeap.poll();
            long rest = total - largest;
            if (largest == 1 || rest == 1) return true;
            if (rest == 0 || largest <= rest || largest % rest == 0) return false;
            long prev = largest % rest;
            total = rest + prev;
            maxHeap.offer(prev);
        }
    }
}

var isPossible = function(target) {
    let total = 0n;
    const maxHeap = [];
    const push = (val) => {
        maxHeap.push(val);
        let i = maxHeap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (maxHeap[p] >= maxHeap[i]) break;
            [maxHeap[p], maxHeap[i]] = [maxHeap[i], maxHeap[p]];
            i = p;
        }
    };
    const pop = () => {
        const top = maxHeap[0];
        const bottom = maxHeap.pop();
        if (maxHeap.length > 0) {
            maxHeap[0] = bottom;
            let i = 0;
            while (true) {
                let left = 2 * i + 1, right = 2 * i + 2, best = i;
                if (left < maxHeap.length && maxHeap[left] > maxHeap[best]) best = left;
                if (right < maxHeap.length && maxHeap[right] > maxHeap[best]) best = right;
                if (best === i) break;
                [maxHeap[i], maxHeap[best]] = [maxHeap[best], maxHeap[i]];
                i = best;
            }
        }
        return top;
    };
    for (const x of target) {
        total += BigInt(x);
        push(BigInt(x));
    }
    while (true) {
        const largest = pop();
        const rest = total - largest;
        if (largest === 1n || rest === 1n) return true;
        if (rest === 0n || largest <= rest || largest % rest === 0n) return false;
        const prev = largest % rest;
        total = rest + prev;
        push(prev);
    }
};
